(* [comment removed for export] *)
Lemma rs_direct : forall src, 0 < FseNCount.Zlength src -> 128 <= Znth 0 src ->
  read_stats src =
    if FseNCount.Zlength src <? (Znth 0 src - 127 + 1) / 2 + 1 then Err ZSTD_error_srcSize_wrong
    else if HUF_SYMBOLVALUE_MAX + 1 <=? Znth 0 src - 127 then Err ZSTD_error_corruption_detected
    else let! cells := direct_loop src (S (Z.to_nat (Znth 0 src - 127))) 0 (Znth 0 src - 127) [] in
         rs_tail (firstn (Z.to_nat (Znth 0 src - 127)) cells) (Znth 0 src - 127) ((Znth 0 src - 127 + 1) / 2).
