Lemma collect_step : forall ws n rank wt, 0 <= n < zlen ws ->
  collect_loop (skipn (Z.to_nat n) ws) rank wt =
    if HUF_TABLELOG_MAX <? Znth n ws then Err ZSTD_error_corruption_detected
    else let! r := load rank (Znth n ws) in
         let! rank' := store rank (Znth n ws) (u32 (r + 1)) in
         let! p := shl32 1 (Znth n ws) in
         collect_loop (skipn (Z.to_nat (n + 1)) ws) rank' (u32 (wt + p / 2)).
Proof.
