Lemma direct_step : forall src fuel n oSize acc, n < oSize ->
  direct_loop src (S fuel) n oSize acc =
    let! b := load src (1 + n / 2) in
    let! _ := assert (n + 1 <? HUF_SYMBOLVALUE_MAX + 1) in
    direct_loop src fuel (n + 2) oSize (acc ++ [b / 16; Z.land b 15]).
Proof.
