(* [comment removed for export] *)
Definition rres (HW RK NSP TLP : Z) (R : res hstats) (m' : fmem) (a0v : Z) : Prop :=
  match R with
  | Ok h => a0v = hs_ret h
            /\ (exists jrest, u8arr usegs m' HW (map (Z_to_bv 8) (hs_weights h) ++ jrest) /\ zlen jrest = 256 - hs_nbSymbols h)
            /\ u32arr usegs m' RK (map (Z_to_bv 64) (hs_rank h))
            /\ rw_cells usegs m' NSP [C4 (Z_to_bv 64 (hs_nbSymbols h))]
            /\ rw_cells usegs m' TLP [C4 (Z_to_bv 64 (hs_tableLog h))]
  | Err e => a0v = - e /\ 0 < e < 120
  | Ub | NoFuel => False
  end.

(* [comment removed for export] *)
Fixpoint all_acc (P : Z -> bool) (x : Z) (n : nat) (acc : bool) : bool :=
  match n with O => acc | S k => all_acc P (x + 1) k (acc && P x) end.

